  /**
   * Side-effect-free reachability check (GET /models) used while waiting out a provider failure. Any answer other
   * than 408/429/5xx shows the server is serving again; the first endpoint that answers becomes active.
   * `preferAlternate` starts with the next endpoint, so a request of unknown status is resubmitted elsewhere
   * when another endpoint is available.
   */
  async probeAvailability(signal?: AbortSignal, opts: { timeoutMs?: number; preferAlternate?: boolean } = {}): Promise<ProbeResult> {
    const total = this.endpoints.length;
    const start = opts.preferAlternate && total > 1 ? (this.activeEndpointIndex + 1) % total : this.activeEndpointIndex;
    let last: ProbeResult = { available: false, condition: "TEMPORARILY_UNAVAILABLE" };
    for (let i = 0; i < total; i++) {
      const idx = (start + i) % total;
      const timeout = AbortSignal.timeout(opts.timeoutMs ?? 5_000);
      try {
        const res = await fetch(`${this.endpoints[idx]}/models`, {
          headers: this.authorization(this.endpoints[idx]),
          signal: signal ? AbortSignal.any([timeout, signal]) : timeout,
          ...this.fetchPolicy(),
        });
        const body = await res.text().catch(() => "");
        if (res.status < 500 && res.status !== 429 && res.status !== 408) {
          this.activeEndpointIndex = idx;
          return { available: true, condition: "AVAILABLE", httpStatus: res.status };
        }
        const hints = providerHints(res.headers, body);
        last = { ...classifyHttpFailure(res.status, hints, body), available: false, httpStatus: res.status, hints, detail: `HTTP ${res.status}` };
      } catch (err: any) {
        if (signal?.aborted) throw err;
        const chain = transportCauseChain(err);
        const { condition } = classifyTransportFailure(chain, "connect", err?.name === "TimeoutError");
        last = { available: false, condition, detail: `${err?.message ?? err}${formatCause(chain)}`, ...(err?.name === "TimeoutError" ? { timedOut: true } : {}), codes: chain.flatMap((c) => (c.code ? [c.code] : [])) };
        if (!TEMPORARY_CONDITIONS.has(condition)) return last;
      }
    }
    return last;
  }

  async chatCompletion(
    messages: ChatMessage[],
    tools: ToolDefinition[],
    requestId: string = randomUUID(),
    signal?: AbortSignal,
    /** Receipt role override for auxiliary calls (e.g. "compaction"). */
    purpose?: string,
  ): Promise<ChatMessage> {
    await this.reverifyExpiredKind(signal);
    const response = await this.withReceipt(requestId, purpose, () =>
      this.withOAuthRetry(this.endpoint, requestId, () => this.withParameterRetry(() => this.chatCompletionOnce(messages, tools, requestId, signal))),
    );
    return response;
  }

  private async chatCompletionOnce(messages: ChatMessage[], tools: ToolDefinition[], requestId: string, signal?: AbortSignal): Promise<ChatMessage> {
    if (this.conn.protocol !== "openai-chat") return this.nativeCompletion(messages, tools, undefined, requestId, signal, this.conn.streamOnly);
    if (this.conn.streamOnly) return this.chatCompletionStreamOnce(messages, tools, undefined, requestId, signal);
    return this.executeWithFailover("chatCompletion", async (currentEp) => {
      if (signal?.aborted) throw abortedError(requestId);
      const url = `${currentEp}/chat/completions`;
      await this.prepareCredential(currentEp, requestId);
      this.preflight(currentEp, requestId, JSON.stringify(messages).length + JSON.stringify(tools).length);
    }
    this.resumedProviderWaits = this.resumedProviderWaits.filter((w) => !covering.includes(w));
    const at = iso(this.recoveryClock.now());
    track({ ...record, state: "RESUMED", updatedAt: at, resumedAt: at, waitedMs: delay });
  }

  /** Recovery of the current inference step; null when no provider failure is being waited out. */
  public getProviderRecovery(): ProviderRecoveryRecord | null {
    return this.activeProviderRecovery;
  }

  /**
   * 3 s startup reachability check (`GET /models`, REQ-TUI-105). Returns an actionable warning naming the endpoint,
   * cause and fix (`nexus doctor`, `~/.config/nexus/config.env`, `/connect`) when unreachable or rejected; undefined when ok.
   */
  public async probeStartupEndpoint(signal?: AbortSignal): Promise<string | undefined> {
    const problem = await this.probeEndpointProblem(signal);
    return problem ? startupProblemWarning(problem) : undefined;
  }

  /** The same probe, structured: what is wrong (unreachable, credentials rejected) and the raw cause; undefined when usable. */
  public async probeEndpointProblem(signal?: AbortSignal, timeoutMs = 3_000): Promise<StartupEndpointProblem | undefined> {
    if (typeof this.client.probeAvailability !== "function") return undefined;
    // After a resume the hosts probe right after restoring: inside the provider's window nothing is sent. The
    // resumed turn waits it out and re-probes through live recovery, so no warning is lost.
    if (this.isProviderWindowOpen()) return undefined;
    try {
      const probe = await this.client.probeAvailability(signal, { timeoutMs });
      if (probe.available && probe.httpStatus !== undefined && probe.httpStatus >= 200 && probe.httpStatus < 300) {
        this.client.markSucceeded?.(this.client.endpoint);
      }
      return startupEndpointProblem(this.client.endpoint, probe);
    } catch {
      return undefined;
    }
  }

  public setProviderRecoveryHooks(hooks: Pick<RecoveryHooks<unknown>, "onFailure" | "shouldYield"> | undefined): void {
    this.providerRecoveryHooks = hooks;
  }

  private onProviderRecoveryState(
    record: ProviderRecoveryRecord,
    turn: NonNullable<AutonomousAgent["activeTurn"]>,
    discardedPartialOutput: boolean,
  ): void {
    this.activeProviderRecovery = record;
    const waiting = record.state === "WAITING" || record.state === "PROBING";
    turn.phase = waiting ? "provider_wait" : "inference";
    this.activity(waiting ? "provider_wait" : "inference");
    const last = record.submissions[record.submissions.length - 1];
    if (record.state === "WAITING") {
      this.ui.stopSpinner(false, `Inference provider ${record.condition.toLowerCase().replace(/_/g, " ")}`);
      const secs = record.nextAttemptAt ? Math.max(0, Math.round((Date.parse(record.nextAttemptAt) - Date.parse(record.updatedAt)) / 1000)) : 0;
      console.warn(pc.yellow(
        `⏳ Provider recovery (step ${record.step}): ${last?.kind ?? "failure"}${last?.httpStatus ? ` HTTP ${last.httpStatus}` : ""}, ` +
        `execution ${last?.execution ?? "UNKNOWN"}; next check in ${secs}s (request ${last?.requestId ?? "?"}).`,
      ));
    } else if (record.state === "RESUMED") {
      console.warn(pc.green(`✓ Provider recovered after ${Math.round(record.waitedMs / 1000)}s; step ${record.step} completed on attempt ${record.submissions.length + 1}.`));
    } else if (record.state === "YIELDED") {
      console.warn(pc.yellow(`↪ Provider ${record.condition.toLowerCase().replace(/_/g, " ")}: step ${record.step} handed back to the operation scheduler (not executed).`));
    } else if (record.state !== "PROBING") {
      console.warn(pc.red(`✗ Provider recovery ${record.state.toLowerCase()}: ${record.reason ?? ""}`));
    }
    if (record.state === "WAITING" || record.state === "RESUMED") {
      try {
        this.checkpointDurableState(`provider recovery ${record.state.toLowerCase()}`);
      } catch (err: any) {
        this.reportPersistenceFailure("provider_recovery", err);
      }
    }
    try {
      this.observer?.onProviderRecovery?.({ record, discardedPartialOutput });
    } catch {}
  }
